/// A simple TOML subset parser that produces deterministic JSON values.
/// Supported: comments (#), blank lines, bare keys, dotted keys,
/// tables, nested tables, strings with standard escapes,
/// integers, booleans, and arrays of those values.
/// Duplicate keys raise an error with a useful message.

suberror TomlError {
  ParseError(String)
} derive(Debug)

///|
fn TomlError::to_string(self : TomlError) -> String {
  match self {
    ParseError(msg) => msg
  }
}

///|
/// Parse TOML text into a JSON value.
/// The result is a JSON object where TOML tables become nested objects.
pub fn parse_toml(text : String) -> Json raise TomlError {
  let root : Map[String, Json] = Map::new()
  let cur_table : Map[String, Json] = root
  let mut table_stack : Array[Map[String, Json]] = [root]
  let mut table_path : Array[String] = []
  let _ = cur_table // used indirectly via table_stack

  let lines = text.split("\n").to_array()
  let mut line_no = 0

  while line_no < lines.length() {
    let raw = lines[line_no]
    line_no = line_no + 1

    // Strip trailing whitespace (but keep leading for now)
    let trimmed = raw.trim()

    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed[0] == '#' as Int {
      continue
    }

    // Check for table header
    if trimmed[0] == '[' as Int {
      // Find matching ]
      let maybe_close = find_matching_bracket(trimmed, 0)
      let (close_idx, _) = maybe_close

      let path_str = trimmed.sub(1, close_idx - 1).trim()
      let keys = parse_dotted_key(path_str)

      // Navigate to the table, creating intermediate objects as needed
      let mut target = root
      let mut i = 0
      while i < keys.length() {
        let key = keys[i]
        if target.contains(key) {
          let existing = target[key]
          // If we're at the last key and existing is not an object, it's a duplicate
          match existing {
            Json::Object(obj) => {
              target = obj
            }
            _ => {
              if i == keys.length() - 1 {
                raise TomlError::ParseError(
                  "Duplicate table key at line \{line_no}: '\{path_str}'"
                )
              }
              // Otherwise, create a new object
              let new_obj : Map[String, Json] = Map::new()
              target[key] = Json::Object(new_obj)
              target = new_obj
            }
          }
        } else {
          let new_obj : Map[String, Json] = Map::new()
          target[key] = Json::Object(new_obj)
          target = new_obj
        }
        i = i + 1
      }
      table_stack = [target]
      continue
    }

    // Should be a key-value pair
    let eq_pos = find_first_eq(trimmed)
    if eq_pos == -1 {
      raise TomlError::ParseError(
        "Invalid line at line \{line_no}: '\{trimmed}'"
      )
    }

    let key_part = trimmed.sub(0, eq_pos).trim()
    let val_part = trimmed.sub(eq_pos + 1, trimmed.length() - eq_pos - 1).trim()

    let keys = parse_dotted_key(key_part)
    let value = parse_value(val_part, line_no)?

    // Navigate to the right place in the current table
    let cur_target = if table_stack.length() > 0 {
      table_stack[table_stack.length() - 1]
    } else {
      root
    }

    // For dotted keys, create intermediate objects
    set_nested_value(cur_target, keys, value, line_no)?
  }

  Json::Object(root)
}

///|
fn find_first_eq(s : String) -> Int {
  let mut i = 0
  while i < s.length() {
    let c = s[i]
    // Skip strings
    if c == '"' as Int {
      i = i + 1
      while i < s.length() {
        if s[i] == '\\' as Int {
          i = i + 2
        } else if s[i] == '"' as Int {
          break
        } else {
          i = i + 1
        }
      }
    } else if c == '=' as Int {
      return i
    }
    i = i + 1
  }
  -1
}

///|
fn find_matching_bracket(s : String, start : Int) -> (Int, Int) {
  let mut depth = 1
  let mut i = start + 1
  while i < s.length() && depth > 0 {
    let c = s[i]
    if c == '[' as Int {
      depth = depth + 1
    } else if c == ']' as Int {
      depth = depth - 1
      if depth == 0 {
        return (i, i - start - 1)
      }
    }
    i = i + 1
  }
  fail("unmatched bracket")
}

///|
fn parse_dotted_key(s : String) -> Array[String] {
  let parts : Array[String] = []
  let mut current = StringBuilder::new()
  let mut i = 0
  let chars = to_char_array(s)
  while i < chars.length() {
    let c = chars[i]
    if c == '.' {
      parts.push(current.to_string())
      current = StringBuilder::new()
    } else if c != ' ' && c != '\t' {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string()
  if last.length() > 0 {
    parts.push(last)
  }
  parts
}

///|
fn to_char_array(s : String) -> Array[Char] {
  let arr : Array[Char] = []
  for c in s {
    arr.push(c)
  }
  arr
}

///|
fn parse_value(s : String, line_no : Int) -> Json raise TomlError {
  let trimmed = s.trim()
  if trimmed.is_empty() {
    raise TomlError::ParseError(
      "Empty value at line \{line_no}"
    )
  }

  let first = trimmed[0]

  // String
  if first == '"' as Int {
    return parse_string_value(trimmed, line_no)?
  }

  // Boolean
  if trimmed == "true" {
    return Json::True
  }
  if trimmed == "false" {
    return Json::False
  }

  // Array
  if first == '[' as Int {
    return parse_array(trimmed, line_no)?
  }

  // Integer
  parse_integer(trimmed, line_no)
}

///|
fn parse_string_value(s : String, line_no : Int) -> Json raise TomlError {
  if s.length() < 2 || s[0] != '"' as Int {
    raise TomlError::ParseError(
      "Invalid string at line \{line_no}: '\{s}'"
    )
  }
  // Find closing quote, accounting for escapes
  let mut buf = StringBuilder::new()
  let mut i = 1
  while i < s.length() {
    let c = s[i]
    if c == '\\' as Int {
      i = i + 1
      if i >= s.length() {
        raise TomlError::ParseError(
          "Unterminated escape at line \{line_no}"
        )
      }
      let esc = s[i]
      let ch = match esc {
        '"' as Int => '"'
        '\\' as Int => '\\'
        'n' as Int => '\n'
        't' as Int => '\t'
        _ => {
          raise TomlError::ParseError(
            "Invalid escape sequence '\\\{esc}' at line \{line_no}"
          )
        }
      }
      buf.write_char(ch)
    } else if c == '"' as Int {
      // End of string
      return Json::String(buf.to_string())
    } else {
      buf.write_char(s.get_char(i).or("?"))
    }
    i = i + 1
  }
  raise TomlError::ParseError(
    "Unterminated string at line \{line_no}"
  )
}

///|
fn get_char_or(s : String, i : Int, default : Char) -> Char {
  match s.get_char(i) {
    Some(c) => c
    None => default
  }
}

///|
fn parse_integer(s : String, line_no : Int) -> Json raise TomlError {
  let trimmed = s.trim()
  let n : Int = @string.from_str(trimmed) catch {
    _ => raise TomlError::ParseError(
      "Invalid integer at line \{line_no}: '\{trimmed}'"
    )
  }
  Json::number(n.to_double(), repr=trimmed)
}

///|
fn parse_array(s : String, line_no : Int) -> Json raise TomlError {
  if s.length() < 2 {
    raise TomlError::ParseError(
      "Invalid array at line \{line_no}: '\{s}'"
    )
  }

  let inner = s.sub(1, s.length() - 2).trim()
  if inner.is_empty() {
    return Json::Array([])
  }

  let elements = split_array_values(inner, line_no)?
  let mut items : Array[Json] = []
  for elem in elements {
    items.push(parse_value(elem.trim(), line_no)?)
  }
  Json::Array(items)
}

///|
fn split_array_values(s : String, line_no : Int) -> Array[String] raise TomlError {
  let parts : Array[String] = []
  let mut current = StringBuilder::new()
  let mut depth = 0
  let mut in_str = false
  let chars = to_char_array(s)
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if in_str {
      current.write_char(c)
      if c == '\\' {
        i = i + 1
        if i < chars.length() {
          current.write_char(chars[i])
        }
      } else if c == '"' {
        in_str = false
      }
    } else if c == '"' {
      in_str = true
      current.write_char(c)
    } else if c == '[' {
      depth = depth + 1
      current.write_char(c)
    } else if c == ']' {
      depth = depth - 1
      current.write_char(c)
    } else if c == ',' && depth == 0 {
      parts.push(current.to_string().trim())
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string().trim()
  if last.length() > 0 {
    parts.push(last)
  }
  parts
}

///|
fn set_nested_value(
  target : Map[String, Json],
  keys : Array[String],
  value : Json,
  line_no : Int
) -> Unit raise TomolError {
  let mut obj = target
  let last_key = keys[keys.length() - 1]

  let mut i = 0
  while i < keys.length() - 1 {
    let key = keys[i]
    if obj.contains(key) {
      match obj[key] {
        Json::Object(inner_obj) => {
          obj = inner_obj
        }
        _ => {
          let new_obj : Map[String, Json] = Map::new()
          obj[key] = Json::Object(new_obj)
          obj = new_obj
        }
      }
    } else {
      let new_obj : Map[String, Json] = Map::new()
      obj[key] = Json::Object(new_obj)
      obj = new_obj
    }
    i = i + 1
  }

  // Set the value at the last key
  if obj.contains(last_key) {
    raise TomlError::ParseError(
      "Duplicate key at line \{line_no}: '\{last_key}'"
    )
  }
  obj[last_key] = value
}
