      let mut target = root
      let mut i = 0
      while i < keys.length() {
        let key = keys[i]
        if target.contains(key) {
          let existing = target[key]
          match existing {
            Json::Object(obj) => {
              target = obj
            }
            _ => {
              if i == keys.length() - 1 {
                raise TomlError::ParseError(
                  "Duplicate table key at line \{line_no}: '\{path_str}'"
                )
              }
              let new_obj : Map[String, Json] = Map::new()
              target[key] = Json::object(new_obj)
              target = new_obj
            }
          }
        } else {
          let new_obj : Map[String, Json] = Map::new()
          target[key] = Json::object(new_obj)
          target = new_obj
        }
        i = i + 1
      }
      table_stack = [target]
      continue
    }

    // Find '=' sign for key-value pair
    let eq_pos = find_first_eq(trimmed)
    if eq_pos == -1 {
      raise TomlError::ParseError(
        "Invalid line at line \{line_no}: '\{trimmed}'"
      )
    }

    let key_part = trimmed.sub(end=eq_pos).trim().to_owned()
    let val_part = trimmed.sub(start=eq_pos + 1).trim().to_owned()
    let keys = parse_dotted_key(key_part)
    let value = parse_value(val_part, line_no)?

    let cur_target = table_stack[table_stack.length() - 1]
    set_nested_value(cur_target, keys, value, line_no)?
  }

