}

///|
fn find_first_eq(s : String) -> Int {
  let mut i = 0
  while i < s.length() {
    let c = s[i]
    // Skip strings
    if c == 34 {
      i = i + 1
      while i < s.length() {
        if s[i] == 92 {
          i = i + 2
        } else if s[i] == 34 {
          break
        } else {
          i = i + 1
        }
      }
    } else if c == 61 {
      return i
    }
    i = i + 1
  }
  -1
}

///|
fn find_matching_bracket(s : String, start : Int) -> Int {
  let mut depth = 1
  let mut i = start + 1
  while i < s.length() && depth > 0 {
    let c = s[i]
    if c == 91 {
      depth = depth + 1
    } else if c == 93 {
      depth = depth - 1
      if depth == 0 {
        return i
      }
    }
    i = i + 1
  }
  fail("unmatched bracket")
}

///|
fn parse_dotted_key(s : String) -> Array[String] {
  let parts : Array[String] = []
  let mut current = StringBuilder::new()
  let mut i = 0
  let chars = to_char_array(s)
  while i < chars.length() {
    let c = chars[i]
    if c == '.' {
      parts.push(current.to_string())
      current = StringBuilder::new()
    } else if c != ' ' && c != '\t' {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string()
  if last.length() > 0 {
    parts.push(last)
  }
  parts
}

///|
