///|
fn parse_value(s : String, line_no : Int) -> Json raise TomlError {
  if s.is_empty() {
    raise TomlError::ParseError(
      "Empty value at line \{line_no}"
    )
  }

  let first = s[0]

  // String
  if first == 34 {
    return parse_string_value(s, line_no)?
  }

  // Boolean
  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }

  // Array
  if first == 91 {
    return parse_array(s, line_no)?
  }

  // Integer
  parse_integer(s, line_no)
}

///|
fn parse_string_value(s : String, line_no : Int) -> Json raise TomlError {
  if s.length() < 2 || s[0] != 34 {
    raise TomlError::ParseError(
      "Invalid string at line \{line_no}: '\{s}'"
    )
  }
  let mut buf = StringBuilder::new()
  let mut i = 1
  let chars = to_char_array(s)
  while i < chars.length() {
    let c = chars[i]
    if c == '\\' {
      i = i + 1
      if i >= chars.length() {
        raise TomlError::ParseError(
          "Unterminated escape at line \{line_no}"
        )
      }
      let esc = chars[i]
      let ch = match esc {
        '"' => '"'
        '\\' => '\\'
        'n' => '\n'
        't' => '\t'
        _ => {
          raise TomlError::ParseError(
            "Invalid escape sequence '\\\{esc}' at line \{line_no}"
          )
        }
      }
      buf.write_char(ch)
    } else if c == '"' {
      return Json::string(buf.to_string())
    } else {
      buf.write_char(c)
    }
    i = i + 1
  }
  raise TomlError::ParseError(
    "Unterminated string at line \{line_no}"
  )
}

///|
fn parse_integer(s : String, line_no : Int) -> Json raise TomlError {
  let trimmed = s.trim().to_owned()
  let n : Int = @string.from_str(trimmed) catch {
    _ => raise TomlError::ParseError(
      "Invalid integer at line \{line_no}: '\{trimmed}'"
    )
  }
  Json::number(n.to_double(), repr=trimmed)
}

///|
fn parse_array(s : String, line_no : Int) -> Json raise TomlError {
  if s.length() < 2 {
    raise TomlError::ParseError(
      "Invalid array at line \{line_no}: '\{s}'"
    )
  }

  let inner = s.sub(start=1, end=s.length() - 1).trim().to_owned()
  if inner.is_empty() {
    return Json::array([])
  }

  let elements = split_array_values(inner, line_no)?
  let mut items : Array[Json] = []
  for elem_view in elements {
    let elem = elem_view.trim().to_owned()
    items.push(parse_value(elem, line_no)?)
  }
  Json::array(items)
}

///|
fn split_array_values(s : String, line_no : Int) -> Array[String] raise TomlError {
  let parts : Array[String] = []
  let mut current = StringBuilder::new()
  let mut depth = 0
  let mut in_str = false
  let chars = to_char_array(s)
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if in_str {
      current.write_char(c)
      if c == '\\' {
        i = i + 1
        if i < chars.length() {
          current.write_char(chars[i])
        }
      } else if c == '"' {
        in_str = false
      }
    } else if c == '"' {
      in_str = true
      current.write_char(c)
    } else if c == '[' {
      depth = depth + 1
      current.write_char(c)
    } else if c == ']' {
      depth = depth - 1
      current.write_char(c)
    } else if c == ',' && depth == 0 {
      parts.push(current.to_string().trim().to_owned())
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string().trim().to_owned()
  if last.length() > 0 {
    parts.push(last)
  }
  parts
}

///|
fn set_nested_value(
  target : Map[String, Json],
  keys : Array[String],
  value : Json,
  line_no : Int
) -> Unit raise TomlError {
  let mut obj = target
  let last_key = keys[keys.length() - 1]

  let mut i = 0
  while i < keys.length() - 1 {
    let key = keys[i]
    if obj.contains(key) {
      match obj[key] {
        Json::Object(inner_obj) => {
          obj = inner_obj
        }
        _ => {
          let new_obj : Map[String, Json] = Map::new()
          obj[key] = Json::object(new_obj)
          obj = new_obj
        }
      }
    } else {
      let new_obj : Map[String, Json] = Map::new()
      obj[key] = Json::object(new_obj)
      obj = new_obj
    }
    i = i + 1
  }

  // Set the value at the last key
  if obj.contains(last_key) {
    raise TomlError::ParseError(
      "Duplicate key at line \{line_no}: '\{last_key}'"
    )
  }
  obj[last_key] = value
}

///|
test "simple parse" {
  let toml = "name = \"John\"\nage = 30\nactive = true\n"
  let result = parse_toml(toml)?
  inspect(result.stringify(), content="{\"active\":true,\"age\":30,\"name\":\"John\"}")
}

///|
test "table parse" {
  let toml = "[owner]\nname = \"John\"\n[owner.details]\nage = 30\n"
  let result = parse_toml(toml)?
  let json = result.stringify()
  // Should contain nested objects
  inspect(json.contains("\"name\":\"John\""), content="true")
  inspect(json.contains("\"age\":30"), content="true")
}

///|
test "dotted keys" {
  let toml = "a.b.c = 42\n"
  let result = parse_toml(toml)?
  inspect(result.stringify(), content="{\"a\":{\"b\":{\"c\":42}}}")
}

///|
test "array of integers" {
  let toml = "nums = [1, 2, 3]\n"
  let result = parse_toml(toml)?
  inspect(result.stringify(), content="{\"nums\":[1,2,3]}")
}

///|
test "string escapes" {
  let toml = "s = \"hello\\nworld\"\n"
  let result = parse_toml(toml)?
  inspect(result.stringify(), content="{\"s\":\"hello\\nworld\"}")
}

///|
test "blank lines and comments" {
  let toml = "# comment\nkey = \"val\"\n\n[table]\n# another comment\nx = 1\n"
  let result = parse_toml(toml)?
  let json = result.stringify()
  inspect(json.contains("\"key\":\"val\""), content="true")
  inspect(json.contains("\"x\":1"), content="true")
}

///|
test "duplicate key error" {
  let toml = "key = 1\nkey = 2\n"
  let result = match catch parse_toml(toml) {
    Ok(_) => "no error"
    Err(_) => "error"
  }
  inspect(result, content="error")
}

///|
test "invalid input error" {
  let toml = "invalid line without equals\n"
  let result = match catch parse_toml(toml) {
    Ok(_) => "no error"
    Err(_) => "error"
  }
  inspect(result, content="error")
}
"}

