{"path": "/private/tmp/prompt_matrix/runs_flash-x-flashprompt/workspaces/04/lib/toml.mbt", "content": "///|
/// A simple TOML subset parser that produces deterministic JSON values.
/// Supported: comments (#), blank lines, bare keys, dotted keys,
/// tables, nested tables, strings with standard escapes,
/// integers, booleans, and arrays of those values.
/// Duplicate keys raise an error with a useful message.

suberror TomlError {
  ParseError(String)
} derive(Debug)

///|
fn TomlError::to_string(self : TomlError) -> String {
  match self {
    ParseError(msg) => msg
  }
}

///|
/// Parse TOML text into a JSON value.
/// The result is a JSON object where TOML tables become nested objects.
pub fn parse_toml(text : String) -> Json raise TomlError {
  let root : Map[String, Json] = Map::new()
  let mut table_stack : Array[Map[String, Json]] = [root]
  let lines = text.split("\n").to_array()
  let mut line_no = 0

  while line_no < lines.length() {
    let raw_view = lines[line_no]
    line_no = line_no + 1
    let trimmed = raw_view.trim().to_owned()

    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed.length() > 0 && trimmed[0] == 35 {
      continue
    }

    // Check for table header
    if trimmed[0] == 91 {
      let close_idx = find_matching_bracket(trimmed, 0)
      let path_str = trimmed.sub(start=1, end=close_idx).trim().to_owned()
      let keys = parse_dotted_key(path_str)

      let mut target = root
      let mut i = 0
      while i < keys.length() {
        let key = keys[i]
        if target.contains(key) {
          let existing = target[key]
          match existing {
            Json::Object(obj) => {
              target = obj
            }
            _ => {
              if i == keys.length() - 1 {
                raise TomlError::ParseError(
                  "Duplicate table key at line \{line_no}: '\{path_str}'"
                )
              }
              let new_obj : Map[String, Json] = Map::new()
              target[key] = Json::object(new_obj)
              target = new_obj
            }
          }
        } else {
          let new_obj : Map[String, Json] = Map::new()
          target[key] = Json::object(new_obj)
          target = new_obj
        }
        i = i + 1
      }
      table_stack = [target]
      continue
    }

    // Find '=' sign for key-value pair
    let eq_pos = find_first_eq(trimmed)
    if eq_pos == -1 {
      raise TomlError::ParseError(
        "Invalid line at line \{line_no}: '\{trimmed}'"
      )
    }

    let key_part = trimmed.sub(end=eq_pos).trim().to_owned()
    let val_part = trimmed.sub(start=eq_pos + 1).trim().to_owned()
    let keys = parse_dotted_key(key_part)
    let value = parse_value(val_part, line_no)

    let cur_target = table_stack[table_stack.length() - 1]
    set_nested_value(cur_target, keys, value, line_no)
  }

  Json::object(root)
}

///|
fn find_first_eq(s : String) -> Int {
  let mut i = 0
  while i < s.length() {
    let c = s[i]
    if c == 34 {
      i = i + 1
      while i < s.length() {
        if s[i] == 92 {
          i = i + 2
        } else if s[i] == 34 {
          break
        } else {
          i = i + 1
        }
      }
    } else if c == 61 {
      return i
    }
    i = i + 1
  }
  -1
}

///|
fn find_matching_bracket(s : String, start : Int) -> Int {
  let mut depth = 1
  let mut i = start + 1
  while i < s.length() && depth > 0 {
    let c = s[i]
    if c == 91 {
      depth = depth + 1
    } else if c == 93 {
      depth = depth - 1
      if depth == 0 {
        return i
      }
    }
    i = i + 1
  }
  fail("unmatched bracket")
}

///|
fn parse_dotted_key(s : String) -> Array[String] {
  let parts : Array[String] = []
  let mut current = StringBuilder::new()
  let mut i = 0
  let chars = to_char_array(s)
  while i < chars.length() {
    let c = chars[i]
    if c == '.' {
      parts.push(current.to_string())
      current = StringBuilder::new()
    } else if c != ' ' && c != '\t' {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string()
  if last.length() > 0 {
    parts.push(last)
  }
  parts
}

///|
fn to_char_array(s : String) -> Array[Char] {
  let arr : Array[Char] = []
  for c in s {
    arr.push(c)
  }
  arr
}

///|
fn parse_value(s : String, line_no : Int) -> Json raise TomlError {
  if s.is_empty() {
    raise TomlError::ParseError("Empty value at line \{line_no}")
  }

  let first = s[0]

  if first == 34 {
    return parse_string_value(s, line_no)
  }

  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }

  if first == 91 {
    return parse_array(s, line_no)
  }

  parse_integer(s, line_no)
}

///|
fn parse_string_value(s : String, line_no : Int) -> Json raise TomlError {
  if s.length() < 2 || s[0] != 34 {
    raise TomlError::ParseError("Invalid string at line \{line_no}: '\{s}'")
  }
  let buf = StringBuilder::new()
  let mut i = 1
  let chars = to_char_array(s)
  while i < chars.length() {
    let c = chars[i]
    if c == '\\' {
      i = i + 1
      if i >= chars.length() {
        raise TomlError::ParseError("Unterminated escape at line \{line_no}")
      }
      let esc = chars[i]
      let ch = match esc {
        '"' => '"'
        '\\' => '\\'
        'n' => '\n'
        't' => '\t'
        _ => {
          raise TomlError::ParseError(
            "Invalid escape sequence '\\\{esc}' at line \{line_no}"
          )
        }
      }
      buf.write_char(ch)
    } else if c == '"' {
      return Json::string(buf.to_string())
    } else {
      buf.write_char(c)
    }
    i = i + 1
  }
  raise TomlError::ParseError("Unterminated string at line \{line_no}")
}

///|
fn parse_integer(s : String, line_no : Int) -> Json raise TomlError {
  let trimmed = s.trim().to_owned()
  let n : Int = @string.from_str(trimmed) catch {
    _ => raise TomlError::ParseError(
      "Invalid integer at line \{line_no}: '\{trimmed}'"
    )
  }
  Json::number(n.to_double(), repr=trimmed)
}

///|
fn parse_array(s : String, line_no : Int) -> Json raise TomlError {
  if s.length() < 2 {
    raise TomlError::ParseError("Invalid array at line \{line_no}: '\{s}'")
  }

  let inner = s.sub(start=1, end=s.length() - 1).trim().to_owned()
  if inner.is_empty() {
    return Json::array([])
  }

  let elements = split_array_values(inner, line_no)
  let items : Array[Json] = []
  for elem_view in elements {
    let elem = elem_view.trim().to_owned()
    items.push(parse_value(elem, line_no))
  }
  Json::array(items)
}

///|
fn split_array_values(s : String, line_no : Int) -> Array[String] raise TomlError {
  let parts : Array[String] = []
  let current = StringBuilder::new()
  let mut depth = 0
  let mut in_str = false
  let chars = to_char_array(s)
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if in_str {
      current.write_char(c)
      if c == '\\' {
        i = i + 1
        if i < chars.length() {
          current.write_char(chars[i])
        }
      } else if c == '"' {
        in_str = false
      }
    } else if c == '"' {
      in_str = true
      current.write_char(c)
    } else if c == '[' {
      depth = depth + 1
      current.write_char(c)
    } else if c == ']' {
      depth = depth - 1
      current.write_char(c)
    } else if c == ',' && depth == 0 {
      let chunk = current.to_string().trim().to_owned()
      if chunk.length() > 0 {
        parts.push(chunk)
      }
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string().trim().to_owned()
  if last.length() > 0 {
    parts.push(last)
  }
  parts
}

///|
fn set_nested_value(
  target : Map[String, Json],
  keys : Array[String],
  value : Json,
  line_no : Int
) -> Unit raise TomlError {
  let mut obj = target
  let last_key = keys[keys.length() - 1]

  let mut i = 0
  while i < keys.length() - 1 {
    let key = keys[i]
    if obj.contains(key) {
      match obj[key] {
        Json::Object(inner_obj) => {
          obj = inner_obj
        }
        _ => {
          let new_obj : Map[String, Json] = Map::new()
          obj[key] = Json::object(new_obj)
          obj = new_obj
        }
      }
    } else {
      let new_obj : Map[String, Json] = Map::new()
      obj[key] = Json::object(new_obj)
      obj = new_obj
    }
    i = i + 1
  }

  if obj.contains(last_key) {
    raise TomlError::ParseError(
      "Duplicate key at line \{line_no}: '\{last_key}'"
    )
  }
  obj[last_key] = value
}

///|
test "simple parse" {
  let toml = "name = \"John\"\nage = 30\nactive = true\n"
  let result = parse_toml(toml)
  inspect(result.stringify(), content="{\"active\":true,\"age\":30,\"name\":\"John\"}")
